-- projects 0004: project management model (generated by novvus-sdk makemigration, then reviewed).
-- Additive: templates (and their phases, processes, tasks, milestones, dependencies), members,
-- links to CRM opportunities (M2M), phases, processes with stages and transitions, task
-- hierarchy fields, participants, dependencies, milestones, deliverables, risks, approvals.
-- The old one-project-per-opportunity constraint is replaced by project_link (several projects
-- may serve one opportunity). No data is rewritten.
-- down: DROP the new tables, DROP the added columns, DROP INDEX ux_project_org_code and
-- re-create UNIQUE (org_id, opportunity_id) on project.

CREATE TABLE template (
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    kind VARCHAR(20) NOT NULL, 
    progress_strategy VARCHAR(20) NOT NULL, 
    is_active BOOLEAN NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (org_id, name)
);

CREATE INDEX ix_template_org_id ON template (org_id);

CREATE TABLE template_phase (
    template_id UUID NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    position INTEGER NOT NULL, 
    weight NUMERIC(7, 2) NOT NULL, 
    duration_days INTEGER NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(template_id) REFERENCES template (id) ON DELETE CASCADE
);

CREATE INDEX ix_template_phase_org_id ON template_phase (org_id);

CREATE TABLE approval (
    project_id UUID NOT NULL, 
    target_kind VARCHAR(20) NOT NULL, 
    target_id UUID NOT NULL, 
    target_label VARCHAR(200) NOT NULL, 
    requested_by_user_id UUID, 
    approver_user_id UUID, 
    status VARCHAR(20) NOT NULL, 
    decided_at TIMESTAMP WITHOUT TIME ZONE, 
    note VARCHAR(2000) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_approval_org_id ON approval (org_id);

CREATE TABLE phase (
    project_id UUID NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    position INTEGER NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    owner_user_id UUID, 
    start_date DATE, 
    due_date DATE, 
    weight NUMERIC(7, 2) NOT NULL, 
    progress NUMERIC(5, 2) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_phase_org_id ON phase (org_id);

CREATE TABLE project_link (
    project_id UUID NOT NULL, 
    opportunity_id UUID NOT NULL, 
    opportunity_name VARCHAR(200) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
    UNIQUE (project_id, opportunity_id)
);

CREATE INDEX ix_project_link_org_id ON project_link (org_id);

CREATE TABLE project_member (
    project_id UUID NOT NULL, 
    user_id UUID NOT NULL, 
    role VARCHAR(120) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    UNIQUE (project_id, user_id), 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_project_member_org_id ON project_member (org_id);

CREATE TABLE risk (
    project_id UUID NOT NULL, 
    title VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    probability VARCHAR(20) NOT NULL, 
    impact VARCHAR(20) NOT NULL, 
    score INTEGER NOT NULL, 
    owner_user_id UUID, 
    mitigation VARCHAR(4000) NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    review_date DATE, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_risk_org_id ON risk (org_id);

CREATE TABLE template_milestone (
    template_id UUID NOT NULL, 
    template_phase_id UUID, 
    name VARCHAR(200) NOT NULL, 
    offset_days INTEGER NOT NULL, 
    weight NUMERIC(7, 2) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(template_id) REFERENCES template (id) ON DELETE CASCADE, 
    FOREIGN KEY(template_phase_id) REFERENCES template_phase (id) ON DELETE SET NULL
);

CREATE INDEX ix_template_milestone_org_id ON template_milestone (org_id);

CREATE TABLE template_process (
    template_id UUID NOT NULL, 
    template_phase_id UUID, 
    name VARCHAR(200) NOT NULL, 
    position INTEGER NOT NULL, 
    stages VARCHAR(4000) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(template_phase_id) REFERENCES template_phase (id) ON DELETE SET NULL, 
    FOREIGN KEY(template_id) REFERENCES template (id) ON DELETE CASCADE
);

CREATE INDEX ix_template_process_org_id ON template_process (org_id);

CREATE TABLE milestone (
    project_id UUID NOT NULL, 
    phase_id UUID, 
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    due_date DATE, 
    owner_user_id UUID, 
    status VARCHAR(20) NOT NULL, 
    reached_at TIMESTAMP WITHOUT TIME ZONE, 
    weight NUMERIC(7, 2) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(phase_id) REFERENCES phase (id) ON DELETE SET NULL, 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_milestone_org_id ON milestone (org_id);

CREATE TABLE process (
    project_id UUID NOT NULL, 
    phase_id UUID, 
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    position INTEGER NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    owner_user_id UUID, 
    current_stage_id UUID, 
    start_date DATE, 
    due_date DATE, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(phase_id) REFERENCES phase (id) ON DELETE SET NULL, 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);

CREATE INDEX ix_process_org_id ON process (org_id);

CREATE TABLE template_task (
    template_id UUID NOT NULL, 
    template_phase_id UUID, 
    template_process_id UUID, 
    title VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    position INTEGER NOT NULL, 
    offset_days INTEGER NOT NULL, 
    duration_days INTEGER NOT NULL, 
    estimated_hours NUMERIC(8, 2) NOT NULL, 
    weight NUMERIC(7, 2) NOT NULL, 
    priority VARCHAR(20) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(template_id) REFERENCES template (id) ON DELETE CASCADE, 
    FOREIGN KEY(template_process_id) REFERENCES template_process (id) ON DELETE SET NULL, 
    FOREIGN KEY(template_phase_id) REFERENCES template_phase (id) ON DELETE SET NULL
);

CREATE INDEX ix_template_task_org_id ON template_task (org_id);

CREATE TABLE process_stage (
    process_id UUID NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    position INTEGER NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    owner_user_id UUID, 
    is_mandatory BOOLEAN NOT NULL, 
    requires_approval BOOLEAN NOT NULL, 
    entry_conditions VARCHAR(2000) NOT NULL, 
    exit_conditions VARCHAR(2000) NOT NULL, 
    required_evidence VARCHAR(2000) NOT NULL, 
    due_date DATE, 
    started_at TIMESTAMP WITHOUT TIME ZONE, 
    finished_at TIMESTAMP WITHOUT TIME ZONE, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(process_id) REFERENCES process (id) ON DELETE CASCADE
);

CREATE INDEX ix_process_stage_org_id ON process_stage (org_id);

CREATE TABLE template_dependency (
    template_id UUID NOT NULL, 
    predecessor_id UUID NOT NULL, 
    successor_id UUID NOT NULL, 
    kind VARCHAR(20) NOT NULL, 
    lag_days INTEGER NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(predecessor_id) REFERENCES template_task (id) ON DELETE CASCADE, 
    FOREIGN KEY(successor_id) REFERENCES template_task (id) ON DELETE CASCADE, 
    UNIQUE (predecessor_id, successor_id), 
    FOREIGN KEY(template_id) REFERENCES template (id) ON DELETE CASCADE
);

CREATE INDEX ix_template_dependency_org_id ON template_dependency (org_id);

CREATE TABLE process_transition (
    process_id UUID NOT NULL, 
    from_stage_id UUID, 
    to_stage_id UUID, 
    user_id UUID, 
    forced BOOLEAN NOT NULL, 
    note VARCHAR(2000) NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(to_stage_id) REFERENCES process_stage (id) ON DELETE SET NULL, 
    FOREIGN KEY(from_stage_id) REFERENCES process_stage (id) ON DELETE SET NULL, 
    FOREIGN KEY(process_id) REFERENCES process (id) ON DELETE CASCADE
);

CREATE INDEX ix_process_transition_org_id ON process_transition (org_id);

CREATE TABLE deliverable (
    project_id UUID NOT NULL, 
    milestone_id UUID, 
    task_id UUID, 
    name VARCHAR(200) NOT NULL, 
    description VARCHAR(4000) NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    owner_user_id UUID, 
    due_date DATE, 
    delivered_at TIMESTAMP WITHOUT TIME ZONE, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(milestone_id) REFERENCES milestone (id) ON DELETE SET NULL, 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
    FOREIGN KEY(task_id) REFERENCES task (id) ON DELETE SET NULL
);

CREATE INDEX ix_deliverable_org_id ON deliverable (org_id);

CREATE TABLE task_dependency (
    project_id UUID NOT NULL, 
    predecessor_id UUID NOT NULL, 
    successor_id UUID NOT NULL, 
    kind VARCHAR(20) NOT NULL, 
    lag_days INTEGER NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(successor_id) REFERENCES task (id) ON DELETE CASCADE, 
    FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
    UNIQUE (predecessor_id, successor_id), 
    FOREIGN KEY(predecessor_id) REFERENCES task (id) ON DELETE CASCADE
);

CREATE INDEX ix_task_dependency_org_id ON task_dependency (org_id);

CREATE TABLE task_participant (
    task_id UUID NOT NULL, 
    user_id UUID NOT NULL, 
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
    custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    deleted_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(task_id) REFERENCES task (id) ON DELETE CASCADE, 
    UNIQUE (task_id, user_id)
);

CREATE INDEX ix_task_participant_org_id ON task_participant (org_id);

